-- DB制約の更新: reports.status から 'rejected' を削除
ALTER TABLE public.reports DROP CONSTRAINT IF EXISTS reports_status_check;
ALTER TABLE public.reports ADD CONSTRAINT reports_status_check CHECK (status IN ('draft','submitted','approved'));

-- RLSポリシー更新: reports_update_own から 'rejected' を削除
DROP POLICY IF EXISTS "reports_update_own" ON public.reports;
CREATE POLICY "reports_update_own" ON public.reports FOR UPDATE USING (user_id = auth.uid() AND status = 'draft');

-- 既存データをクリーンアップ（CASCADE で関連テーブルも全削除）
DELETE FROM public.approval_threshold_rules;
DELETE FROM public.organizations CASCADE;

-- monthly_salary の精度を拡張（日本円の給与に対応）
ALTER TABLE public.users ALTER COLUMN monthly_salary TYPE NUMERIC(10,2);

