INSERT INTO public.report_comments (report_id, user_id, content, created_at) VALUES
  ('a0000000-0000-0000-0004-000000000001', 'a0000000-0000-0000-0001-000000000002', 'A社の反応はどうでしたか？次のステップを教えてください。', '2026-02-24 09:15:00+09'),
  ('a0000000-0000-0000-0004-000000000001', 'a0000000-0000-0000-0001-000000000004', '先方は前向きです。来週中に見積を提出予定です。', '2026-02-24 10:00:00+09'),
  ('a0000000-0000-0000-0004-000000000007', 'a0000000-0000-0000-0001-000000000003', 'セキュリティ面のレビューも追加でお願いします。', '2026-02-24 10:30:00+09'),
  ('a0000000-0000-0000-0004-000000000007', 'a0000000-0000-0000-0001-000000000005', '承知しました。OWASP Top 10に沿ってチェックします。', '2026-02-24 11:00:00+09'),
  ('a0000000-0000-0000-0004-000000000009', 'a0000000-0000-0000-0001-000000000009', '渡辺さん、APIの認証部分について相談させてください。', '2026-02-26 09:00:00+09'),
  ('a0000000-0000-0000-0004-000000000009', 'a0000000-0000-0000-0001-000000000005', '了解です。午後にSlackで話しましょう。', '2026-02-26 09:30:00+09'),
  ('a0000000-0000-0000-0004-000000000016', 'a0000000-0000-0000-0001-000000000001', 'セミナー参加者数はどのくらいでしたか？', '2026-02-27 09:00:00+09'),
  ('a0000000-0000-0000-0004-000000000016', 'a0000000-0000-0000-0001-000000000006', '42名の参加がありました。目標40名を達成しています。', '2026-02-27 09:30:00+09'),
  ('a0000000-0000-0000-0004-000000000020', 'a0000000-0000-0000-0001-000000000002', '具体的なアプローチ方法をもう少し詳しく記載してもらえますか？', '2026-02-27 10:15:00+09'),
  ('a0000000-0000-0000-0004-000000000026', 'a0000000-0000-0000-0001-000000000001', '来期目標の数字感、事前にすり合わせたいです。', '2026-02-26 09:30:00+09'),
  ('a0000000-0000-0000-0004-000000000026', 'a0000000-0000-0000-0001-000000000002', 'はい、木曜に30分お時間いただけますか？', '2026-02-26 10:00:00+09');
