INSERT INTO public.handovers (store_id, created_by, title, content, priority, category, is_resolved, handover_date) VALUES
  ('a0000000-0000-0000-0009-000000000001', 'a0000000-0000-0000-0001-000000000002', 'VIPテーブル予約', '3/1(土) 20:00~ VIP A様 4名 シャンパンタワー予約済み。特別メニューの準備をお願いします。', 'high', '予約', false, '2026-02-27'),
  ('a0000000-0000-0000-0009-000000000001', 'a0000000-0000-0000-0001-000000000002', '冷蔵庫修理について', '第2冷蔵庫の温度が不安定。3/3にメンテナンス業者が来ます。連絡先: 03-XXXX-YYYY', 'medium', '設備', false, '2026-02-26'),
  ('a0000000-0000-0000-0009-000000000001', 'a0000000-0000-0000-0001-000000000002', '新人研修スケジュール', '3月入社の新スタッフ研修: 3/3〜3/7。はなさんがトレーナー担当。', 'medium', 'スタッフ', false, '2026-02-25'),
  ('a0000000-0000-0000-0009-000000000002', 'a0000000-0000-0000-0001-000000000004', '在庫補充', 'プレミアムウイスキーの在庫が残り2本。早めの発注をお願いします。', 'high', '在庫', false, '2026-02-27'),
  ('a0000000-0000-0000-0009-000000000002', 'a0000000-0000-0000-0001-000000000004', 'レジ機器不具合', 'カード端末の読み取りが時々エラーになります。業者に連絡済み（対応待ち）。', 'medium', '設備', false, '2026-02-26'),
  ('a0000000-0000-0000-0009-000000000003', 'a0000000-0000-0000-0001-000000000008', '常連B様からのリクエスト', 'B様より「いつものボトル」をキープしたいとのこと。銘柄: ○○ 確認して対応お願いします。', 'low', '接客', false, '2026-02-27');
INSERT INTO public.board_posts (organization_id, created_by, title, content, category, target_scope, is_pinned, is_important, view_count, created_at) VALUES
  ('a0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0001-000000000001', '【重要】3月の全体会議について', '3月5日（木）14:00より、全社員参加の全体会議を開催します。\n\n議題:\n1. 2月度業績報告\n2. 3月度方針発表\n3. 新プロジェクト発表\n4. 質疑応答\n\n会場: 本社5F大会議室\n※リモート参加の場合はZoomリンクを後日共有します。', 'general', 'all', true, true, 10, '2026-02-25 09:00:00+09'),
  ('a0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0001-000000000007', '健康診断のお知らせ', '今年度の定期健康診断を以下の日程で実施します。\n\n日程: 2026年3月10日（火）〜12日（木）\n場所: 本社1F 特設会場\n\n対象: 全社員\n予約: 社内ポータルの健診予約フォームより受付中\n\n締切: 3月3日（月）', 'general', 'all', true, false, 8, '2026-02-24 10:00:00+09'),
  ('a0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0001-000000000003', '開発部 コードレビューガイドライン更新', '開発部のコードレビューガイドラインを更新しました。\n\n主な変更点:\n- PRのサイズ上限を500行→300行に変更\n- レビュー完了SLAを48時間→24時間に短縮\n- テストカバレッジ80%以上を必須に\n\n詳細は社内Wikiを確認してください。', 'general', 'department', false, false, 4, '2026-02-23 14:00:00+09'),
  ('a0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0001-000000000002', '営業部 3月キャンペーン実施要項', '3月の新規顧客獲得キャンペーンについてお知らせします。\n\n期間: 3/1〜3/31\n目標: 新規契約15件\n特典: 初月利用料30%OFF\n\n営業資料は共有フォルダにアップ済みです。各自確認の上、積極的にアプローチをお願いします。', 'general', 'department', false, false, 5, '2026-02-26 11:00:00+09'),
  ('a0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0001-000000000012', '社内イベント: 花見のお知らせ', '今年も恒例のお花見を開催します！\n\n日時: 3月28日（土）12:00〜\n場所: 代々木公園（集合場所は後日連絡）\n会費: 2,000円（新入社員無料）\n\n参加希望の方は3/14までに松本までご連絡ください。', 'general', 'all', false, false, 7, '2026-02-27 12:00:00+09'),
  ('a0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0001-000000000007', 'リモートワーク制度の変更について', '4月よりリモートワーク制度を一部変更します。\n\n変更点:\n- 週3日出社→週2日出社に緩和\n- コアタイム: 10:00-15:00（変更なし）\n- フレックス範囲: 7:00-22:00に拡大\n\n詳細は人事ポータルを確認してください。', 'general', 'all', false, false, 11, '2026-02-28 09:00:00+09');
